19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public abstract class OwnerMapper {
24	
25	    @Autowired
26	    protected BulkSignupWarningEvaluator bulkSignupWarningEvaluator;
27	
28	    @Autowired
29	    protected MembershipLevelEvaluator membershipLevelEvaluator;
30	
31	    @Autowired
32	    protected OwnerIdentity ownerIdentity;
33	
34	    @Mapping(target = "identityKey", expression = "java(owner == null ? null : ownerIdentity.key(owner))")
35	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
36	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
37	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
38	    @Mapping(target = "checkDigit", expression = "java(org.springframework.samples.petclinic.model.CheckDigit.forOwner(owner))")
39	    @Mapping(target = "membershipLevel", expression = "java(membershipLevelEvaluator.levelFor(owner))")
40	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
41	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarningEvaluator.isWarranted(owner))")
42	    @Mapping(target = "contactPreference", expression = "java(org.springframework.samples.petclinic.model.ContactPreference.forOwner(owner))")
43	    public abstract OwnerDto toOwnerDto(Owner owner);
44	
45	    /**
46	     * Formats an owner's membership number as {@code "<customerCode>-M<YY>"}, where
47	     * {@code YY} is the last two digits of the registration date's year
48	     * (e.g. {@code "NSW-A1B2C3D4-M26"}). Returns {@code null} until both the customer code
49	     * and registration date have been assigned.
50	     */
51	    protected String formatMembershipNumber(Owner owner) {
52	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
53	            return null;
54	        }
55	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
56	    }
57	
58	    /**
59	     * Derives an owner's locality from its region-and-hash identity: the {@code <REGION>}
60	     * segment of the assigned {@code customerCode}. Owners without a code yet fall back to
61	     * deriving the region straight from their own fields.
62	     */
63	    protected String formatLocality(Owner owner) {
64	        if (owner == null) {
65	            return null;
66	        }
67	        if (owner.getCustomerCode() != null) {
68	            return org.springframework.samples.petclinic.model.Locality.fromCustomerCode(owner.getCustomerCode());
69	        }
70	        return org.springframework.samples.petclinic.model.Locality.forOwner(owner);
71	    }
72	
73	    /**
74	     * Formats an owner's stored names as {@code "LastName, FirstName"} for display.
75	     */
76	    protected String formatDisplayName(Owner owner) {
77	        if (owner == null) {
78	            return null;
79	        }
80	        return owner.getLastName() + ", " + owner.getFirstName();
81	    }
82	
83	    /**
84	     * Builds an owner's initials as the upper-cased first letters of the first and last
85	     * name, dot-separated with a trailing dot (e.g. {@code "J.S."}).
86	     */
87	    protected String formatInitials(Owner owner) {
88	        if (owner == null) {
89	            return null;
90	        }
91	        return initial(owner.getFirstName()) + initial(owner.getLastName());
92	    }
93	
94	    private String initial(String name) {
95	        return Character.toUpperCase(name.charAt(0)) + ".";
96	    }
97	
98	    public abstract Owner toOwner(OwnerDto ownerDto);
99	
100	    @Mapping(target = "id", ignore = true)
101	    @Mapping(target = "pets", ignore = true)
